mapper.select:
select * from conversation c
-- 必要查条件 c.user_id = #{userId} and c.status = 1
-- 如果用户退出时间非空 and c.update_time >= #{quitTime}

mapper.update:
update conversation set latest_msg = #{content}, latest_msg_time = #{sendTime}, status = 1, unread_count = case when user_id in
#{receiverId}
then unread_count + 1 else unread_count end where id = #{conversationId}

update conversation
set is_top = #{isTop}
where id = #{conversationId}
  and user_id = #{userId}

update conversation
set is_mute = #{isMute}
where id = #{conversationId}
  and user_id = #{userId}

update group_conversation
set group_avatar = #{groupAvatar}
where id = #{conversationId}

update group_conversation
set member_count = member_count + 1
where id = #{groupId}

mapper.select:
select group_name as name, group_avatar as avatar
from group_conversation
where id = #{conversationId}

select user_id
from group_member
where group_id = #{conversationId}

mapper.update:
update group_conversation
set member_count = member_count - 1
where id = #{groupId}

update group_conversation
group_name = #{groupName}, group_avatar = #{groupAvatar}, group_desc = #{groupDesc},
where id = #{conversationId}

update group_conversation
set member_count = member_count + #{count}
where id = #{groupId}
